async function applySettings(){const returnToSearch=modalParents.at(-1)?.kind==='search-options';const values={language:$('#prefLanguage').value,theme:$('#prefTheme').value,uiPalette:$('#prefUiPalette').value,codeTheme:$('#prefCodeTheme').value,sourceSwitchWidth:$('#prefSourceSwitchWidth').value,fontSize:$('#prefFont').value,highContrast:$('#prefContrast').checked,animations:$('#prefAnimations').checked,analyticsStyledBars:$('#prefAnalyticsStyledBars').checked,waveVideoBackground:$('#prefWaveVideoBackground').checked,waveVideoWelcome:$('#prefWaveVideoWelcome').checked,holidayVideoWelcome:$('#prefHolidayVideoWelcome').checked,promptExpandStyle:$('#prefPromptExpandStyle').value,remoteImages:$('#prefRemoteImages').value,listMode:$('#prefList').value,pageSize:Number($('#prefPageSize').value),sort:$('#prefSort').value,compact:$('#prefCompact').checked,serverUrl:$('#prefServer').value.trim(),directoryMode:$('#prefDirectoryMode').value,customDirectory:$('#prefDirectory').value.trim(),ollamaUrl:$('#prefOllamaUrl').value.trim(),ollamaModel:$('#prefOllamaModel').value};values.serverAddresses=[...new Set([values.serverUrl,...(state.settings.serverAddresses||[])].filter(Boolean))];const serverChanged=values.serverUrl!==state.settings.serverUrl;if(serverChanged&&mode()==='server'){++threadRequest;threadLoading=false;++listRequest;}flushPosition();try{await saveSettings(values);}catch(error){restoreAppearancePreview();throw error;}closeModal();if(returnToSearch){renderShell();toast(t('saved'));return;}state.page=1;if(serverChanged&&mode()==='server'){state.thread=null;state.threadKey='';state.resourceImageContext=null;}renderShell();await loadCollections();toast(t('saved'));}
function renderSemanticStatus(){const node=$('#semanticStatus');if(!node)return;const s=state.searchStatus||{};const ready=s.modelReady||s.model?.ready||s.semantic?.modelReady||s.ready||false;const count=s.indexedPassages??s.indexedCount??s.passages??s.semantic?.indexedPassages??s.index?.count??0;node.textContent=`${t(ready?'modelReady':'modelNotReady')} · ${t('indexedPassages',{count:formatCount(typeof count==='number'?count:0)})}${s.needsIndexing?' · '+t('indexNeedsUpdate'):''}${s.modelBytes!=null?' · '+t('modelSize',{size:bytesLabel(s.modelBytes)}):''}${s.indexBytes!=null?' · '+t('modelIndexSize',{size:bytesLabel(s.indexBytes)}):''}`;const text=$('#textIndexStatus'),index=s.textIndex;if(text)text.textContent=index?.preview?t('searchPreviewIndex'):t('searchTextIndex')+' · '+t(index?.ready&&!index?.needsIndexing?'searchIndexReady':'indexNeedsUpdate')+(index?.bytes!=null?' · '+bytesLabel(index.bytes):'');}
