let ollamaDiscovery=null,ollamaRequest=0,ollamaTestRequest=0,ollamaSession=0;
function renderOllamaDiscovery(result,preferredModel){
 if(modalKind!=='settings'||!$('#prefOllamaModel'))return;
 ollamaDiscovery=result;
 const known=(result.models||[]).map(m=>typeof m==='string'?m:m.name||m.model).filter(Boolean);
 const unknown=(result.details||[]).filter(m=>m.embedding==='unknown').map(m=>m.name).filter(Boolean);
 const names=[...new Set([...known,...unknown])];
 const selectNode=$('#prefOllamaModel');const selected=preferredModel||selectNode.value||state.settings.ollamaModel;
 const missing=selected&&!names.includes(selected);if(missing)names.unshift(selected);
 selectNode.innerHTML=option('',t('selectModel'))+names.map(name=>option(name,missing&&name===selected?`${name} (${t('modelMissing')})`:unknown.includes(name)?`${name} (${t('testRequired')})`:name,selected)).join('');
 const available=result.available!==false;
 $('#ollamaStatus').className=`ollama-status ${available&&known.length?'success':''}`;
 $('#ollamaStatus').textContent=available?(known.length?t('ollamaConnected',{count:known.length}):t('noModels')):t(result.installed&&result.isLocal?'ollamaStopped':'ollamaUnavailable');
 $('#ollamaStart').disabled=!!result.available||!result.installed||!result.isLocal;
 $('#ollamaTest').disabled=!available||!selectNode.value||!!missing;
 renderInstalledModels(result);
 if(result.suggestedModel&&!$('#ollamaDownloadModel').value)$('#ollamaDownloadModel').value=result.suggestedModel;
}
async function loadOllamaModels(){
 const node=$('#prefOllamaUrl');if(!node)return;const url=node.value.trim()||state.settings.ollamaUrl,request=++ollamaRequest;$('#ollamaStatus').textContent=t('loading');$('#ollamaStart').disabled=true;
 const result=await invoke('ollama.models',{url});if(request!==ollamaRequest||modalKind!=='settings'||$('#prefOllamaUrl').value.trim()!==url)return;renderOllamaDiscovery(result);
}
async function startOllama(){const url=$('#prefOllamaUrl').value.trim(),session=ollamaSession;$('#ollamaStart').disabled=true;$('#ollamaStatus').textContent=t('loading');const result=await runOperation('ollama.start',t('startOllama'),()=>invoke('ollama.start',{url}));if(result&&modalKind==='settings'&&session===ollamaSession&&$('#prefOllamaUrl').value.trim()===url)renderOllamaDiscovery(result);}
async function testOllama(){
 const url=$('#prefOllamaUrl').value.trim(),model=$('#prefOllamaModel').value,request=++ollamaTestRequest,session=ollamaSession;if(!model)throw new Error(t('modelRequired'));
 const current=()=>modalKind==='settings'&&session===ollamaSession&&request===ollamaTestRequest&&$('#prefOllamaUrl')?.value.trim()===url&&$('#prefOllamaModel')?.value===model;
 $('#ollamaTest').disabled=true;$('#ollamaTestStatus').textContent=t('loading');try{const result=await runOperation('ollama.test',t('testOllama'),()=>invoke('ollama.test',{url,model}));if(!result||!current())return;$('#ollamaTestStatus').textContent=t(result.compatible?'ollamaTestPassed':'ollamaTestFailed',{dimensions:result.dimensions||0});}finally{if(current())$('#ollamaTest').disabled=!$('#prefOllamaModel').value;}
}
