let readingEntries=[],readingDialogScope=null;
async function renderReadingEntries(){
 const request=++readingRenderRequest,tab=readingTab,scope=readingDialogScope||activeReadingSource();
 const recent=Array.isArray(state.reading.recent)?state.reading.recent:Object.entries(state.reading.recent||{}).map(([key,v])=>({key,...v}));
 let entries=(tab==='bookmarks'?state.reading.bookmarks:[...recent].map(e=>typeof e==='string'?{key:e,...state.reading.positions[e]}:e)).filter(entry=>matchesReadingSource(entry,scope));
 if(!entries.length&&tab==='recent')entries=Object.entries(state.reading.positions).map(([key,value])=>({key,...value})).filter(entry=>matchesReadingSource(entry,scope)).reverse();
 const host=$('#readingEntries');if(!host)return;
 if(tab==='bookmarks'){
  host.innerHTML=`<p class="fine">${esc(t('loading'))}</p>`;
  const summaries=await Promise.all(entries.map(entry=>{const ref=refFromEntry(entry);return ref&&canContainHiddenThoughts(entry)?thoughtsView.resolve(keyFor(ref),ref):null;}));
  if(request!==readingRenderRequest||readingTab!==tab||modalKind!=='reading')return;
  entries=entries.filter((entry,index)=>!isHiddenViewEntry(entry,summaries[index]));
 }
 if(request!==readingRenderRequest||!$('#readingEntries'))return;readingEntries=entries;
 $('#readingEntries').innerHTML=readingEntries.length?readingEntries.map((entry,index)=>{const ref=refFromEntry(entry)||{},position=entry.position||state.reading.positions[entry.key]||entry;return `<div class="reading-item">${icon(tab==='bookmarks'?'bookmark':'history')}<button type="button" class="reading-main" data-action="reading-open" data-index="${index}"><strong>${esc(entry.title||position.title||ref.conversationKey||t('untitled'))}</strong><span class="fine">${esc(t('readingSource',{mode:t(ref.mode==='server'?'serverOnly':'localOnly'),collection:ref.collection||''}))}${entry.turnIndex!=null?` · ${esc(t('messageNumber',{number:entry.turnIndex+1}))}`:''}</span></button>${tab==='bookmarks'?iconButton('reading-remove',t('remove'),'trash',`data-index="${index}"`):''}</div>`;}).join(''):`<p class="fine">${esc(t(tab==='bookmarks'?'noBookmarks':'noRecent'))}</p>`;
}
async function openReading(index){const entry=readingEntries[index],ref=refFromEntry(entry);if(!ref)return;closeModal();const changeMode=ref.mode!==mode();if(ref.mode==='server'&&canonicalUrl(ref.serverUrl)!==canonicalUrl(state.settings.serverUrl)){++threadRequest;threadLoading=false;++listRequest;flushPosition();await rememberServer(ref.serverUrl);if(!changeMode){renderCaption();await loadCollections();}}if(changeMode)await switchMode(ref.mode||'local');await openThread(ref,readingTab==='bookmarks'?{turnIndex:entry.turnIndex,role:entry.role}:undefined);}
