function positionSearchTooltip(){const button=$('#searchHelpButton'),tip=$('#searchHelpTooltip');if(!button||!tip)return;const box=button.getBoundingClientRect(),width=tip.offsetWidth||310,height=tip.offsetHeight||90;tip.style.left=Math.max(12,Math.min(innerWidth-width-12,box.right-width))+'px';tip.style.top=(box.bottom+height+16<innerHeight?box.bottom+7:Math.max(12,box.top-height-7))+'px';}
