document.addEventListener('mouseover',event=>{if(event.target.closest('#searchHelpButton'))positionSearchTooltip();});
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const handler=actions[el.dataset.action];if(handler){event.preventDefault();safe(()=>handler(el,event));}});
document.addEventListener('submit',event=>{if(event.target.id==='searchForm'){event.preventDefault();safe(updateSearch);}else if(event.target.id==='readerSearch'){event.preventDefault();findInReader(1);}else if(event.target.id==='settingsForm'){event.preventDefault();safe(applySettings);}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='collectionSelect')safe(async()=>{thoughtsView.clear();++readingRenderRequest;await saveSettings({[mode()==='server'?'serverCollection':'localCollection']:el.value});state.page=1;await loadFiles();});else if(el.id==='listSort')safe(async()=>{await saveSettings({sort:el.value});state.page=1;await loadFiles();});else if(el.id==='searchMethod'){if($('#searchRole'))$('#searchRole').disabled=el.value==='titles';if($('#searchOptionHelp'))$('#searchOptionHelp').textContent=searchMethodHelp(el.value);el.title=searchMethodHelp(el.value);if($('#searchHelpButton')){$('#searchHelpButton').title=searchMethodHelp(el.value);$('#searchHelpButton').setAttribute('aria-label',searchMethodHelp(el.value));$('#searchHelpTooltip').textContent=searchMethodHelp(el.value);}}else if(el.id==='prefUiPalette'||el.id==='prefCodeTheme'){const prefix=el.id==='prefUiPalette'?'palette':'code';const description=t(prefix+'Description_'+el.value);el.title=description;$('#'+el.id+'Description').textContent=description;}else if(el.id==='prefOllamaModel'){++ollamaTestRequest;if($('#ollamaTest'))$('#ollamaTest').disabled=!el.value||ollamaDiscovery?.available===false||!(ollamaDiscovery?.models||[]).some(m=>(typeof m==='string'?m:m.name||m.model)===el.value)&&!(ollamaDiscovery?.details||[]).some(m=>m.name===el.value&&m.embedding==='unknown');if($('#ollamaTestStatus'))$('#ollamaTestStatus').textContent='';}else if(el.classList.contains('transfer-check'))updateTransferSelection();});
document.addEventListener('change',event=>{if(event.target.closest('[data-settings-panel="appearance"]')&&event.target.id!=='prefLanguage')previewAppearance();});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='archiveSearch'){clearTimeout(searchTimer);$('.clear-search').hidden=!el.value;searchTimer=setTimeout(()=>safe(updateSearch),state.searchMode==='ollama'||state.searchMode==='semantic'||state.searchMode==='hybrid'?900:300);}else if(el.id==='prefOllamaUrl'){++ollamaRequest;++ollamaTestRequest;ollamaDiscovery=null;$('#ollamaStart').disabled=true;$('#ollamaTest').disabled=true;$('#ollamaStatus').textContent=t('loadModels');$('#ollamaTestStatus').textContent='';}else if(el.id==='readerFindInput')findInReader(1);else if(el.id==='transferUrl'&&$('#transferCopy')){$('#transferCopy').disabled=true;$('#transferStatus').textContent=t('reloadCollections');}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='resourcesCacheEnabled'){safe(()=>updateResources('resources.settings',{enabled:el.checked}));}else if(el.id==='storageProfile'){manager.compressionChoice=el.value;const apply=$('[data-action="storage-convert"]');if(apply)apply.disabled=el.value===manager.status?.storage?.profile||!!state.operation;}else if(el.dataset.managerCollection){el.checked?manager.selectedCollections.add(el.dataset.managerCollection):manager.selectedCollections.delete(el.dataset.managerCollection);renderManager();}else if(el.dataset.managerFile){el.checked?manager.selected.add(el.dataset.managerFile):manager.selected.delete(el.dataset.managerFile);renderManager();}else if(el.id==='managerCollection'||el.id==='managerProvider'){manager[el.id==='managerCollection'?'collectionId':'provider']=el.value;safe(()=>loadManagerFiles());}else if(el.id==='managerDestination')$('#managerNewNameField').hidden=el.value!=='__new__';else if(el.id==='managerMoveFirst')$('#managerDestinationFields').hidden=!el.checked;});
document.addEventListener('toggle',event=>{if(event.target.matches?.('.manager-overview'))manager.overviewOpen=event.target.open;},true);
document.addEventListener('input',event=>{if(event.target.id==='managerCollectionQuery'){const input=event.target,position=input.selectionStart;manager.collectionQuery=input.value;renderManager();$('#managerCollectionQuery')?.focus();$('#managerCollectionQuery')?.setSelectionRange(position,position);}});
document.addEventListener('keydown',event=>{
 if(event.key==='Enter'&&event.target.closest('#managerRoot')&&event.target.tagName!=='BUTTON'){event.preventDefault();if(event.target.id==='managerQuery')safe(managerActions['manager-search']);else if(manager.dialog?.stage==='edit'&&event.target.tagName==='INPUT')safe(nextManagerDialog);return;}
 if(event.key==='Escape'&&manager.dialog&&$('#managerRoot')?.getClientRects().length){event.preventDefault();managerActions['manager-dialog-cancel']();return;}
 if(event.key==='Escape'){if(modalKind){closeModal();event.preventDefault();}else if(!$('#readerSearch')?.hidden){$('#readerSearch').hidden=true;reader?.find('',1);event.preventDefault();}return;}
 if(modalKind&&event.key==='Tab'){const focusable=$$('.modal button:not([disabled]), .modal input:not([disabled]), .modal select:not([disabled]), .modal [tabindex="0"]').filter(el=>el.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
 if((event.ctrlKey||event.metaKey)&&!event.altKey){if(event.key.toLowerCase()==='f'&&!modalKind){event.preventDefault();setWorkspace('reader');openFind();}else if(event.key.toLowerCase()==='k'&&!modalKind){event.preventDefault();setWorkspace('reader');safe(()=>setSearchExpanded(true,true));}else if(event.key===','){event.preventDefault();showSettings();}else if(event.key.toLowerCase()==='o'){event.preventDefault();showImport();}}
});
window.addEventListener('beforeunload',flushPosition);
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(modalKind==='settings')previewAppearance();else applyTheme();});
async function boot(){
 state.settings={...state.settings,...startupAppearance(bridge?.startupAppearance)};t=translator(state.settings.language);applyTheme();showStartupLoader($('#app'),state.settings.language);
 if(!bridge?.invoke){$('#app').innerHTML=`<div class="app-loading"><p>${esc(t('desktopOnly'))}</p></div>`;$('#app').setAttribute('aria-busy','false');return;}
 try{const data=await invoke('bootstrap');state.settings={...state.settings,...data.settings};state.reading=normalizeReading(data.reading);state.holidayStatus=data.holidayStatus||null;state.dataDir=data.dataDir;state.version=data.version||'1.3.0';state.revision=Number(data.revision)||0;state.searchStatus=data.searchStatus||{};state.resources=data.resources||null;restoreSearchPreferences();t=translator(state.settings.language);applyTheme();renderShell();bridge.onProgress?.(progress=>{analytics?.progress(progress);receiveSearchProgress(progress);if(!state.operation){if(progress.operation==='search'&&state.loading)setStatus(progress.message||t('searchBusy'));return;}state.operation={...state.operation,...progress};renderOperation();});bridge.onMenu?.(action=>{const map={settings:'settings',preferences:'settings',import:'import-dialog',open:'import-dialog',about:'about',find:'find-open'};const handler=actions[map[action]||action];if(handler)safe(()=>handler());});await loadCollections();}
 catch(error){$('#app').innerHTML=`<div class="welcome"><div class="welcome-inner"><h1>${esc(t('error'))}</h1><p>${esc(error.message||error)}</p>${button('boot-retry',t('retry'),'refresh','primary')}</div></div>`;$('#app').setAttribute('aria-busy','false');actions['boot-retry']=boot;}
}
boot();
